use xiom.io;
type Pair[T,U] = {
  first: T;
  second: U;
}

fn main() -> Int {
  let greeting: Pair[Str,Str] = Pair[Str,Str]{ first: "Hello", second: "World" };
  io.println(greeting.first.to_str());
  io.println(greeting.second.to_str());

  let data: Pair[Int,Bool] = Pair[Int,Bool]{ first: 42, second: true };
  io.println(data.first.to_str());
  io.println(data.second.to_str());
  return 0;
}
